N = int(input())
X = list(map(int, input().split()))

if N == 1:
    print(0)
    exit()

for k in range(N):
    ans = 10**9
    if k > 0:
        ans = min(ans, max(X[k] - X[0], X[-1] - X[k - 1]) // 2)
    if k + 1 < N:
        ans = min(ans, max(X[k + 1] - X[0], X[-1] - X[k]) // 2)
    print(ans)
